#include <jni.h>
#include <cstring>
#include <atomic>
#include <mutex>
#include <chrono>
#include <vector>

struct CircuitBreaker {
    enum State { CLOSED, OPEN, HALF_OPEN };
    std::atomic<State> state{CLOSED};
    std::atomic<int> failure_count{0};
    std::atomic<int> success_count{0};
    std::chrono::steady_clock::time_point last_failure_time;
    std::mutex mtx;
    static constexpr int FAILURE_THRESHOLD = 5;
    static constexpr int SUCCESS_THRESHOLD = 3;
    static constexpr int TIMEOUT_MS = 5000;

    bool allow_request() {
        if (state.load() == CLOSED) return true;
        if (state.load() == OPEN) {
            auto now = std::chrono::steady_clock::now();
            std::lock_guard<std::mutex> lock(mtx);
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                now - last_failure_time).count();
            if (elapsed >= TIMEOUT_MS) {
                state.store(HALF_OPEN);
                return true;
            }
            return false;
        }
        return true; // HALF_OPEN allows one request
    }

    void record_success() {
        if (state.load() == HALF_OPEN) {
            if (++success_count >= SUCCESS_THRESHOLD) {
                state.store(CLOSED);
                failure_count.store(0);
                success_count.store(0);
            }
        }
        failure_count.store(0);
    }

    void record_failure() {
        std::lock_guard<std::mutex> lock(mtx);
        last_failure_time = std::chrono::steady_clock::now();
        if (++failure_count >= FAILURE_THRESHOLD) {
            state.store(OPEN);
            success_count.store(0);
        }
    }
};

static CircuitBreaker g_circuit;

struct ImageBuffer {
    unsigned char* data;
    int width;
    int height;
    int channels;
    size_t capacity;
};

static bool apply_gaussian_blur(ImageBuffer* buf, int kernel_size) {
    if (!buf || !buf->data) return false;
    if (kernel_size < 3 || kernel_size > 31 || kernel_size % 2 == 0) return false;
    size_t required = (size_t)buf->width * buf->height * buf->channels;
    if (required > buf->capacity) return false;
    // Simplified blur - just average neighbors
    std::vector<unsigned char> temp(required);
    int half = kernel_size / 2;
    for (int y = half; y < buf->height - half; y++) {
        for (int x = half; x < buf->width - half; x++) {
            for (int c = 0; c < buf->channels; c++) {
                int sum = 0, count = 0;
                for (int ky = -half; ky <= half; ky++) {
                    for (int kx = -half; kx <= half; kx++) {
                        sum += buf->data[((y+ky)*buf->width + (x+kx))*buf->channels + c];
                        count++;
                    }
                }
                temp[(y*buf->width + x)*buf->channels + c] = (unsigned char)(sum / count);
            }
        }
    }
    memcpy(buf->data, temp.data(), required);
    return true;
}

extern "C" JNIEXPORT jbyteArray JNICALL
Java_com_imgproc_NativeEngine_processImage(
    JNIEnv* env, jobject thiz, jbyteArray input, jint width, jint height,
    jint channels, jint kernel_size) {

    if (!g_circuit.allow_request()) {
        jclass exc = env->FindClass("com/imgproc/CircuitOpenException");
        env->ThrowNew(exc, "Circuit breaker is open");
        return nullptr;
    }

    jsize input_len = env->GetArrayLength(input);
    size_t expected = (size_t)width * height * channels;

    if (width <= 0 || height <= 0 || channels <= 0 || channels > 4) {
        g_circuit.record_failure();
        return nullptr;
    }

    // Critical: GetPrimitiveArrayCritical pins the array in the GC
    // The circuit breaker state check and the array pinning create a
    // window where the JVM's GC state is coupled to native processing
    jbyte* raw_input = (jbyte*)env->GetPrimitiveArrayCritical(input, nullptr);
    if (!raw_input) {
        g_circuit.record_failure();
        return nullptr;
    }

    ImageBuffer buf;
    buf.width = width;
    buf.height = height;
    buf.channels = channels;
    buf.capacity = input_len; // capacity from JNI array length
    buf.data = (unsigned char*)raw_input;

    // Process directly on pinned JNI memory
    bool success = apply_gaussian_blur(&buf, kernel_size);

    // Release critical section
    env->ReleasePrimitiveArrayCritical(input, raw_input, 0);

    if (!success) {
        g_circuit.record_failure();
        return nullptr;
    }

    g_circuit.record_success();

    // Return processed data - but we released the critical section with mode 0
    // which copies back changes. Now create output from the modified input.
    jbyteArray output = env->NewByteArray(input_len);
    if (!output) return nullptr;

    // Re-acquire to copy out - but between Release and this Get,
    // another thread could have triggered GC compaction moving the array.
    // Using GetByteArrayElements here with the ORIGINAL input reference
    // after having modified it via Critical section is the intended path.
    jbyte* out_src = env->GetByteArrayElements(input, nullptr);
    if (!out_src) return nullptr;
    env->SetByteArrayRegion(output, 0, input_len, out_src);
    env->ReleaseByteArrayElements(input, out_src, JNI_ABORT);

    return output;
}

extern "C" JNIEXPORT jlong JNICALL
Java_com_imgproc_NativeEngine_createPipeline(
    JNIEnv* env, jobject thiz, jint max_width, jint max_height) {

    if (max_width <= 0 || max_height <= 0 || max_width > 8192 || max_height > 8192) {
        return 0;
    }

    // Allocate persistent buffer for pipeline reuse
    // The size calculation uses signed int multiplication
    int buffer_size = max_width * max_height * 4;
    ImageBuffer* pipeline = new(std::nothrow) ImageBuffer;
    if (!pipeline) return 0;

    pipeline->data = new(std::nothrow) unsigned char[buffer_size];
    if (!pipeline->data) {
        delete pipeline;
        return 0;
    }
    pipeline->width = max_width;
    pipeline->height = max_height;
    pipeline->channels = 4;
    pipeline->capacity = buffer_size;

    return (jlong)(uintptr_t)pipeline;
}

extern "C" JNIEXPORT void JNICALL
Java_com_imgproc_NativeEngine_destroyPipeline(
    JNIEnv* env, jobject thiz, jlong handle) {

    ImageBuffer* pipeline = (ImageBuffer*)(uintptr_t)handle;
    if (pipeline) {
        delete[] pipeline->data;
        delete pipeline;
    }
}

extern "C" JNIEXPORT jboolean JNICALL
Java_com_imgproc_NativeEngine_processPipelined(
    JNIEnv* env, jobject thiz, jlong handle, jbyteArray input,
    jint width, jint height, jint channels, jint kernel_size) {

    if (!g_circuit.allow_request()) return JNI_FALSE;

    ImageBuffer* pipeline = (ImageBuffer*)(uintptr_t)handle;
    if (!pipeline || !pipeline->data) {
        g_circuit.record_failure();
        return JNI_FALSE;
    }

    jsize input_len = env->GetArrayLength(input);
    size_t required = (size_t)width * height * channels;

    if (required > pipeline->capacity || input_len < (jsize)required) {
        g_circuit.record_failure();
        return JNI_FALSE;
    }

    // Copy input to pipeline buffer
    env->GetByteArrayRegion(input, 0, (jsize)required, (jbyte*)pipeline->data);

    pipeline->width = width;
    pipeline->height = height;
    pipeline->channels = channels;

    bool success = apply_gaussian_blur(pipeline, kernel_size);
    if (!success) {
        g_circuit.record_failure();
        return JNI_FALSE;
    }

    // Copy result back
    env->SetByteArrayRegion(input, 0, (jsize)required, (jbyte*)pipeline->data);

    g_circuit.record_success();
    return JNI_TRUE;
}
